const lib = require("vt2-vuln-lib");

// TOP-LEVEL (module-scope) module._compile(...) -- same VT-307c-fix-7
// widening construct as ADV2-054's own vt2-holder, kept here so the
// never-imported top-level vt2-vuln-lib@1.9.0 instance stays a genuine
// UNKNOWN (not a false NOT_AFFECTED) rather than trivially reachable or
// trivially clean. The regression this scenario actually targets is
// entirely about how the ENTRYPOINT reaches this file at all -- see
// src/index.ts.
const pluginName = process.env.ADV2_055_PLUGIN;
module._compile(`require(${JSON.stringify(pluginName)});`, __filename);

function useHolder() {
  return lib.dangerousOp();
}

module.exports = { useHolder };
